function wrap(ctx,text,max){let rows=[],s='';for(const ch of text){if(ctx.measureText(s+ch).width>max&&s){rows.push(s);s=ch}else s+=ch}if(s)rows.push(s);return rows}function rounded(ctx,x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
async function createCardCanvas(){const snapshot=cards.map(c=>c?[...c]:null),done=new Set(marks);await document.fonts.ready;if(document.fonts.load)await document.fonts.load('24px CardPencil');const paths=['assets/paper.jpg','assets/pink-paper.jpg','assets/bingo-collage.png?v=2','assets/lace-top.png','assets/lace-bottom.png','assets/self-love.png','assets/pink-felt-frame-rounded.png','assets/leopard-star.png','assets/card-sheet.png',...snapshot.filter(Boolean).map(iconPath),...snapshot.filter(c=>c&&c[3]).map(c=>c[3])];const images=await Promise.all(paths.map(loadArtwork));const [paper,pink,title,laceTop,laceBottom,selfLove,feltFrame,starImage]=images;const lookup=new Map(paths.map((p,i)=>[p,images[i]]));const c=document.createElement('canvas');c.width=1800;c.height=2440;const ctx=c.getContext('2d');ctx.fillStyle='#fbf5e9';ctx.fillRect(0,0,c.width,c.height);ctx.globalAlpha=.65;ctx.fillStyle=ctx.createPattern(paper,'repeat');ctx.fillRect(0,0,c.width,c.height);ctx.globalAlpha=1;ctx.drawImage(laceTop,0,0,1800,95);ctx.textAlign='center';ctx.fillStyle='#a4667e';ctx.font='26px serif';ctx.drawImage(selfLove,420,105,780,261);ctx.drawImage(title,660,325,610,275);ctx.fillStyle='#956c7b';ctx.font='29px "Noto Serif SC", serif';
snapshot.forEach((card,i)=>{if(!card)return;const x=105+i%3*540,y=615+Math.floor(i/3)*540,w=510;const index=Math.max(0,defaults.findIndex(c=>c[1]===card[1]&&c[2]===card[2]));const xs=[34,282,526,773,1017],ys=[17,265,519,761,999];ctx.save();if(done.has(i)){ctx.fillStyle='#eee3c9';rounded(ctx,x,y,w,w,35);ctx.globalAlpha=.35}if(card[3]){drawPhotoCard(ctx,lookup.get(card[3]),displayText(card),x,y,w)}else if(card[0]!==defaults[index][0]||language==='en'){ctx.fillStyle=cardBackgrounds[index];rounded(ctx,x,y,w,w,35);ctx.save();ctx.beginPath();ctx.rect(x,y,w,w*(index===12?.58:.68));ctx.clip();ctx.drawImage(lookup.get('assets/card-sheet.png'),xs[index%5],ys[Math.floor(index/5)],234,234,x,y,w,w);ctx.restore();ctx.fillStyle='#654758';ctx.font='32px sans-serif';const rows=wrap(ctx,displayText(card),w-50);const lineHeight=Math.min(40,w*.25/Math.max(rows.length,1));const firstY=y+w*.84-(rows.length-1)*lineHeight/2;rows.forEach((text,j)=>ctx.fillText(text,x+w/2,firstY+j*lineHeight))}else ctx.drawImage(lookup.get('assets/card-sheet.png'),xs[index%5],ys[Math.floor(index/5)],234,234,x,y,w,w);ctx.globalAlpha=1;if(done.has(i)){ctx.translate(x+w/2,y+w/2);ctx.rotate(-7*Math.PI/180);ctx.drawImage(starImage,-w*.39,-w*.39,w*.78,w*.78)}ctx.restore()});
const words=language==='en'?['Be','kind','to','yourself']:['今天','也要','好好','爱自己'];ctx.font='40px "Noto Serif SC",serif';words.forEach((word,i)=>{ctx.save();ctx.translate(560+i*225,2300);ctx.rotate((i%2?1:-1)*.035);ctx.fillStyle='#b4a096';ctx.fillRect(-83,-40,172,77);ctx.fillStyle=i%2?'#edb6cc':'#f6d1df';ctx.fillRect(-88,-46,172,77);ctx.strokeStyle='#b47a91';ctx.lineWidth=1.5;ctx.strokeRect(-88,-46,172,77);ctx.fillStyle='#654758';ctx.fillText(word,-2,7);ctx.restore()});ctx.drawImage(laceBottom,0,2347,1800,93);return c}

$('#download').onclick=async()=>{const btn=$('#download');btn.disabled=true;btn.textContent=tr('正在制作图片…','Creating your image…');try{const c=await createCardCanvas();const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!blob)throw Error('export');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=tr('好好爱自己-Bingo.png','self-care-bingo.png');a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast(tr('卡片已生成，愿你把温柔带在身边 ♡','Your card is ready ♡'))}catch{toast(tr('图片生成失败，请再试一次','Could not create the image. Please try again.'))}finally{btn.disabled=false;btn.textContent=tr('↓ 下载我的卡片','↓ Save my card')}};
function tr(zh,en){return language==='en'?en:zh}
function updateLanguage(){document.documentElement.lang=language==='en'?'en':'zh-CN';document.title=tr('自我关爱 Bingo','Self-care Bingo');document.querySelector('.plan-heading .sr-only').textContent=tr('自我关爱 Bingo','Self-care Bingo');$('#close').setAttribute('aria-label',tr('关闭','Close'));$('#shuffle').title=tr('重新抽取卡片并重置点亮记录','Shuffle cards and reset progress');$('#languageToggle').textContent=language==='en'?'中文':'EN';$('#welcomeStart').textContent=tr('开始制作卡片','Create your card');document.querySelector('.welcome-panel p').textContent=tr('把爱自己做成小游戏','Turn self-care into a little game');document.querySelector('.welcome-chinese').textContent=tr('爱自己','Self-care');$('#shuffle').textContent=tr('⤨ 随机换一组','⤨ Shuffle cards');$('#completeHint').textContent=tr('填满九宫格，就可以完成计划。','Fill all nine spaces to continue.');$('#download').textContent=tr('↓ 下载我的卡片','↓ Save my card');document.querySelectorAll('.scrapbook-note span').forEach((el,i)=>el.textContent=(language==='en'?['Be','kind','to','yourself']:['今天','也要','好好','爱自己'])[i]);render()}
$('#languageToggle').onclick=()=>{language=language==='zh'?'en':'zh';try{localStorage.setItem('bingo-language',language)}catch(e){}updateLanguage()};
updateLanguage();


function addIllustration(button,card){
 if(card[3]){photoLayer(button,card[3]);return}
 const index=Math.max(0,defaults.findIndex(c=>c[1]===card[1]&&c[2]===card[2]));
 const art=document.createElement('span');art.className='illustrated-art';art.setAttribute('aria-hidden','true');
 const image=document.createElement('img');image.src='assets/card-sheet.png';image.draggable=false;
 const col=index%5,row=Math.floor(index/5);const xs=[34,282,526,773,1017],ys=[17,265,519,761,999];
 image.style.width=(1281/234*100)+'%';image.style.height=(1227/234*100)+'%';image.style.left=(-xs[col]/234*100)+'%';image.style.top=(-ys[row]/234*100)+'%';
 const custom=card[0]!==defaults[index][0]||language==='en';if(custom){const artHeight=index===12?.58:.68;button.classList.add('custom-card');button.style.setProperty('--card-background',cardBackgrounds[index]);button.style.setProperty('--art-height',(artHeight*100)+'%');image.style.height=(1227/(234*artHeight)*100)+'%';image.style.top=(-ys[row]/(234*artHeight)*100)+'%'}art.append(image);button.prepend(art);
}
let bonusTimer;
function celebrateLine(){
 document.querySelector('.bonus-party')?.remove();clearTimeout(bonusTimer);
 const party=document.createElement('div');party.className='bonus-party';party.setAttribute('aria-hidden','true');
 for(const side of [-1,1]){for(let n=0;n<26;n++){
 const bit=document.createElement('i');bit.className='party-bit '+(['ribbon','star','petal'][n%3]);
 bit.style.setProperty('--side',side);bit.style.setProperty('--x',(side*(70+Math.random()*260))+'px');bit.style.setProperty('--y',(-130-Math.random()*420)+'px');bit.style.setProperty('--spin',((Math.random()-.5)*720)+'deg');bit.style.setProperty('--delay',(Math.random()*.18)+'s');
 bit.style.backgroundColor=['#e9a5bc','#e5be69','#aab695','#b8c9dd','#c4afd0'][n%5];party.append(bit);
 }}
 document.body.append(party);bonusTimer=setTimeout(()=>party.remove(),2000);
}
